// Run the complete original KataGo 10b 19x19 ONNX network as ONE FP16
// graph on a pinned MediaTek Neuron device, validate all 5 network heads.
// The packet is generated by tools/export_katago_neuron_full.py.
// No CPU fallback or split device scheduling. Only report NN evals/s when
// whole-network output matches isolated ONNX Runtime CPU reference.
#include <dlfcn.h>
#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <limits>
#include <memory>
#include <numeric>
#include <stdexcept>
#include <string>
#include <vector>

struct NeuronDevice;
struct NeuronModel;
struct NeuronCompilation;
struct NeuronExecution;
struct NeuronOperandType {
    int32_t type; uint32_t dimensionCount; const uint32_t* dimensions; float scale; int32_t zeroPoint;
};
static constexpr uint32_t FLAG_CONST=1,FLAG_INPUT=2,FLAG_OUTPUT=4;
template<class F> F sym(void* handle,const char* symbol) {
    void* p=dlsym(handle,symbol);
    if(!p)throw std::runtime_error(std::string("Missing Neuron symbol ")+symbol);
    return reinterpret_cast<F>(p);
}
static void check(int error,const char* operation) {
    if(error)throw std::runtime_error(std::string(operation)+" returned rc="+std::to_string(error));
}
static double percentile(const std::vector<double>& samples,double frac) {
    const double index=(samples.size()-1)*frac;
    const size_t a=static_cast<size_t>(index),b=std::min(samples.size()-1,a+1);
    return samples[a]+(samples[b]-samples[a])*(index-a);
}

struct Operand {
    uint32_t type=0,flags=0;
    std::vector<uint32_t> dims;
    std::vector<char> data;
};
struct Operation {
    uint32_t type;
    std::vector<uint32_t> inputs,outputs;
};
struct Output {
    std::string name;
    std::vector<float> golden;
};
struct Packet {
    std::vector<Operand> operands;
    std::vector<Operation> operations;
    std::vector<uint32_t> inputs,outputs;
    std::vector<Output> refs;
};

static void take(std::ifstream& f,void* dst,size_t bytes) {
    if(bytes==0)return;
    f.read(static_cast<char*>(dst),bytes);
    if(!f)throw std::runtime_error("Full-network packet truncated");
}
static uint32_t integer(std::ifstream& f) {
    uint32_t value=0;take(f,&value,sizeof(value));return value;
}
static size_t elementCount(const Operand& x) {
    size_t n=1;
    for(uint32_t d:x.dims) {
        if(!d||n>10'000'000/d)throw std::runtime_error("Invalid FP16 operand dimensions");
        n*=d;
    }
    return n;
}
static Packet parse(const char* filename) {
    std::ifstream f(filename,std::ios::binary);
    if(!f)throw std::runtime_error(std::string("Cannot open full-network packet ")+filename);
    char magic[8]={};
    take(f,magic,8);
    if(std::memcmp(magic,"K10NW001",8))throw std::runtime_error("Expected full KataGo K10NW001 packet");
    uint32_t nOperands=integer(f),nOps=integer(f),nInputs=integer(f),nOutputs=integer(f);
    if(nOperands<50||nOperands>2000||nOps<100||nOps>1000||nInputs!=2||nOutputs!=5)
        throw std::runtime_error("Invalid full KataGo graph dimensions");
    Packet p;
    p.operands.reserve(nOperands);
    for(uint32_t i=0;i<nOperands;i++) {
        Operand operand;
        uint32_t type=integer(f),rank=integer(f),flags=integer(f),bytes=integer(f);
        uint32_t dims[4]={};take(f,dims,sizeof(dims));
        if(rank>4||bytes>128*1024*1024)
            throw std::runtime_error("Invalid operand rank or constant size");
        operand.type=type;operand.flags=flags;
        operand.dims.assign(dims,dims+rank);
        operand.data.resize(bytes);
        take(f,operand.data.data(),operand.data.size());
        const size_t count=elementCount(operand);
        const size_t elemBytes=(type==8?2:4);
        if((flags&(FLAG_CONST|FLAG_INPUT)) && elemBytes*count!=bytes) {
            // Android BOOL (type=6) scalar values are one byte.
            if(!(type==6 && bytes==1 && count==1))
                throw std::runtime_error("Constant or input bytes != expected operand size "+std::to_string(i));
        }
        p.operands.push_back(std::move(operand));
    }
    p.operations.reserve(nOps);
    for(uint32_t i=0;i<nOps;i++) {
        Operation op{};
        op.type=integer(f);
        const uint32_t nin=integer(f),nout=integer(f);
        if(nin<1||nin>32||nout!=1)throw std::runtime_error("Invalid operation input/output count");
        op.inputs.resize(nin);op.outputs.resize(nout);
        take(f,op.inputs.data(),nin*4);
        take(f,op.outputs.data(),nout*4);
        for(uint32_t index:op.inputs)if(index>=nOperands)throw std::runtime_error("Operation input index invalid");
        for(uint32_t index:op.outputs)if(index>=nOperands)throw std::runtime_error("Operation output index invalid");
        p.operations.push_back(std::move(op));
    }
    p.inputs.resize(nInputs);p.outputs.resize(nOutputs);
    take(f,p.inputs.data(),nInputs*4);take(f,p.outputs.data(),nOutputs*4);
    for(uint32_t index:p.inputs)if(index>=nOperands)throw std::runtime_error("External input index invalid");
    for(uint32_t index:p.outputs)if(index>=nOperands)throw std::runtime_error("External output index invalid");
    for(uint32_t i=0;i<nOutputs;i++) {
        uint32_t nameLen=integer(f);
        if(nameLen<1||nameLen>256)throw std::runtime_error("Invalid output name");
        std::string name(nameLen,'\0');
        take(f,&name[0],nameLen);
        uint32_t bytes=integer(f);
        if(bytes!=elementCount(p.operands[p.outputs[i]])*4)
            throw std::runtime_error("CPU golden length mismatches tensor "+name);
        Output ref;ref.name=std::move(name);
        ref.golden.resize(bytes/4);
        take(f,ref.golden.data(),bytes);
        p.refs.push_back(std::move(ref));
    }
    char extra;
    if(f.read(&extra,1))throw std::runtime_error("Extra bytes after full-network packet");
    return p;
}

static int execute(void* lib,const Packet& p,const std::string& deviceName,int warmup,int runs) {
    auto getDeviceCount=sym<int (*)(uint32_t*)>(lib,"Neuron_getDeviceCount");
    auto getDevice=sym<int (*)(uint32_t,NeuronDevice**)>(lib,"Neuron_getDevice");
    auto getDeviceName=sym<int (*)(const NeuronDevice*,const char**)>(lib,"NeuronDevice_getName");
    auto createModel=sym<int (*)(NeuronModel**)>(lib,"NeuronModel_create");
    auto freeModel=sym<void (*)(NeuronModel*)>(lib,"NeuronModel_free");
    auto addOperand=sym<int (*)(NeuronModel*,const NeuronOperandType*)>(lib,"NeuronModel_addOperand");
    auto setValue=sym<int (*)(NeuronModel*,int32_t,const void*,size_t)>(lib,"NeuronModel_setOperandValue");
    auto addOperation=sym<int (*)(NeuronModel*,int32_t,uint32_t,const uint32_t*,uint32_t,const uint32_t*)>(
        lib,"NeuronModel_addOperation");
    auto modelIO=sym<int (*)(NeuronModel*,uint32_t,const uint32_t*,uint32_t,const uint32_t*)>(
        lib,"NeuronModel_identifyInputsAndOutputs");
    auto finishModel=sym<int (*)(NeuronModel*)>(lib,"NeuronModel_finish");
    auto opSupport=sym<int (*)(const NeuronModel*,const NeuronDevice* const*,uint32_t,bool*)>(
        lib,"NeuronModel_getSupportedOperationsForDevices");
    auto createCompilation=sym<int (*)(NeuronModel*,const NeuronDevice* const*,uint32_t,NeuronCompilation**)>(
        lib,"NeuronCompilation_createForDevices");
    auto finishCompilation=sym<int (*)(NeuronCompilation*)>(lib,"NeuronCompilation_finish");
    auto freeCompilation=sym<void (*)(NeuronCompilation*)>(lib,"NeuronCompilation_free");
    auto createExecution=sym<int (*)(NeuronCompilation*,NeuronExecution**)>(lib,"NeuronExecution_create");
    auto setInput=sym<int (*)(NeuronExecution*,int32_t,const NeuronOperandType*,const void*,size_t)>(
        lib,"NeuronExecution_setInput");
    auto setOutput=sym<int (*)(NeuronExecution*,int32_t,const NeuronOperandType*,void*,size_t)>(
        lib,"NeuronExecution_setOutput");
    auto compute=sym<int (*)(NeuronExecution*)>(lib,"NeuronExecution_compute");
    auto freeExecution=sym<void (*)(NeuronExecution*)>(lib,"NeuronExecution_free");

    uint32_t nDevices=0;check(getDeviceCount(&nDevices),"Neuron_getDeviceCount");
    if(nDevices>64)throw std::runtime_error("Unreasonable Neuron device count");
    NeuronDevice* device=nullptr;
    for(uint32_t i=0;i<nDevices;i++) {
        NeuronDevice* d=nullptr;const char* name=nullptr;
        check(getDevice(i,&d),"Neuron_getDevice");
        check(getDeviceName(d,&name),"NeuronDevice_getName");
        std::printf("Neuron device[%u]: %s\n",i,name?name:"(unknown)");
        if(name && deviceName==name)device=d;
    }
    if(!device)throw std::runtime_error("Requested pinned Neuron device unavailable: "+deviceName);
    const NeuronDevice* devices[]={device};
    NeuronModel* model=nullptr;
    NeuronCompilation* compilation=nullptr;
    NeuronExecution* exec=nullptr;
    try {
        check(createModel(&model),"NeuronModel_create");
        for(size_t i=0;i<p.operands.size();i++) {
            const Operand& o=p.operands[i];
            NeuronOperandType desc={int32_t(o.type),uint32_t(o.dims.size()),
                                    o.dims.empty()?nullptr:o.dims.data(),0,0};
            check(addOperand(model,&desc),"NeuronModel_addOperand");
            if(o.flags&FLAG_CONST) {
                check(setValue(model,int32_t(i),o.data.data(),o.data.size()),"NeuronModel_setOperandValue");
            }
        }
        for(size_t i=0;i<p.operations.size();i++) {
            const Operation& op=p.operations[i];
            int rc=addOperation(model,int32_t(op.type),op.inputs.size(),op.inputs.data(),
                                op.outputs.size(),op.outputs.data());
            if(rc)throw std::runtime_error("NeuronModel_addOperation index="+std::to_string(i)+
                                           " type="+std::to_string(op.type)+" rc="+std::to_string(rc));
        }
        check(modelIO(model,p.inputs.size(),p.inputs.data(),p.outputs.size(),p.outputs.data()),
              "NeuronModel_identifyInputsAndOutputs");
        check(finishModel(model),"NeuronModel_finish");
        std::unique_ptr<bool[]> supported(new bool[p.operations.size()]{});
        check(opSupport(model,devices,1,supported.get()),"NeuronModel_getSupportedOperationsForDevices");
        size_t missing=0;
        for(size_t i=0;i<p.operations.size();i++) {
            if(!supported[i]) {
                if(missing<20)
                    std::printf("KATAGO_FULL_UNSUPPORTED_OP index=%zu type=%u\n",i,p.operations[i].type);
                missing++;
            }
        }
        std::printf("KATAGO_FULL_DEVICE_SUPPORT device=%s ops=%zu unsupported=%zu\n",
                    deviceName.c_str(),p.operations.size(),missing);
        std::fflush(stdout);
        if(missing)throw std::runtime_error("Full KataGo graph not completely supported by selected MDLA device");

        auto compileStart=std::chrono::steady_clock::now();
        check(createCompilation(model,devices,1,&compilation),"NeuronCompilation_createForDevices");
        check(finishCompilation(compilation),"NeuronCompilation_finish");
        const double compileMs=std::chrono::duration<double,std::milli>(
            std::chrono::steady_clock::now()-compileStart).count();
        std::printf("KATAGO_FULL_COMPILE device=%s ops=%zu compile_ms=%.3f\n",
                    deviceName.c_str(),p.operations.size(),compileMs);
        std::fflush(stdout);
        check(createExecution(compilation,&exec),"NeuronExecution_create");

        std::vector<std::vector<uint16_t>> outputs(p.outputs.size());
        for(size_t i=0;i<p.inputs.size();i++) {
            const Operand& operand=p.operands[p.inputs[i]];
            check(setInput(exec,int32_t(i),nullptr,operand.data.data(),operand.data.size()),
                  "NeuronExecution_setInput");
        }
        for(size_t i=0;i<p.outputs.size();i++) {
            const Operand& operand=p.operands[p.outputs[i]];
            outputs[i].resize(elementCount(operand));
            check(setOutput(exec,int32_t(i),nullptr,outputs[i].data(),outputs[i].size()*2),
                  "NeuronExecution_setOutput");
        }
        for(int i=0;i<warmup;i++)check(compute(exec),"NeuronExecution_compute(warmup)");
        std::vector<double> times;times.reserve(runs);
        for(int i=0;i<runs;i++) {
            auto t=std::chrono::steady_clock::now();
            check(compute(exec),"NeuronExecution_compute");
            times.push_back(std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-t).count());
        }
        size_t totalWrong=0;
        for(size_t k=0;k<p.outputs.size();k++) {
            double maxAbs=0,sumAbs=0;
            size_t wrong=0;
            for(size_t i=0;i<outputs[k].size();i++) {
                _Float16 half;std::memcpy(&half,&outputs[k][i],sizeof(half));
                float got=static_cast<float>(half),ref=p.refs[k].golden[i];
                double delta=std::fabs(double(got)-double(ref));
                if(!std::isfinite(got)||!std::isfinite(ref))delta=INFINITY;
                maxAbs=std::max(maxAbs,delta);
                sumAbs+=delta;
                if(delta>0.05+0.06*std::fabs(double(ref)))wrong++;
            }
            totalWrong+=wrong;
            std::printf("KATAGO_FULL_VERIFY output=%s wrong=%zu/%zu max_abs=%.6f mean_abs=%.6f\n",
                        p.refs[k].name.c_str(),wrong,outputs[k].size(),maxAbs,sumAbs/outputs[k].size());
        }
        if(totalWrong)throw std::runtime_error("One or more complete KataGo output heads disagree with ONNX CPU");
        std::sort(times.begin(),times.end());
        double mean=std::accumulate(times.begin(),times.end(),0.0)/times.size();
        std::printf("KATAGO_FULL_NN_PASS device=%s mean=%.3f ms p50=%.3f ms p95=%.3f ms nn_evals_per_sec=%.2f\n",
                    deviceName.c_str(),mean,percentile(times,.5),percentile(times,.95),1000.0/mean);
        std::puts("NOTE: COMPLETE KataGo 10b neural network, batch=1, 19x19 full board; NN-only, not MCTS.");
    } catch(...) {
        if(exec)freeExecution(exec);
        if(compilation)freeCompilation(compilation);
        if(model)freeModel(model);
        throw;
    }
    freeExecution(exec);
    freeCompilation(compilation);
    freeModel(model);
    return 0;
}

int main(int argc,char** argv) {
    try {
        if(argc<2||argc>5)throw std::runtime_error("Usage: katago_full_neuron graph.bin [mtk-mdla] [warmup] [runs]");
        Packet p=parse(argv[1]);
        const std::string device=argc>2?argv[2]:"mtk-mdla";
        const int warmup=argc>3?std::stoi(argv[3]):5;
        const int runs=argc>4?std::stoi(argv[4]):20;
        if(warmup<0||runs<1||runs>10000)throw std::runtime_error("Invalid warmup/runs");
        void* lib=dlopen("libneuronusdk_adapter.9.mtk.so",RTLD_NOW|RTLD_LOCAL);
        if(!lib)lib=dlopen("libneuronusdk_adapter.mtk.so",RTLD_NOW|RTLD_LOCAL);
        if(!lib)throw std::runtime_error("Could not load MediaTek Neuron Adapter");
        std::printf("KATAGO_FULL_GRAPH device=%s operands=%zu operations=%zu inputs=%zu outputs=%zu\n",
                    device.c_str(),p.operands.size(),p.operations.size(),p.inputs.size(),p.outputs.size());
        int result=execute(lib,p,device,warmup,runs);
        dlclose(lib);
        return result;
    } catch(const std::exception& error) {
        std::fprintf(stderr,"KATAGO_FULL_NN_FAIL: %s\n",error.what());
        return 1;
    }
}
